@router.post('/api/avatars/upload-policy')
def create_avatar_upload_policy(
    payload: AvatarUploadRequest,
    s3: Any = Depends(get_s3_client),
    current_user: User = Depends(get_current_user)
):
    s3_key = f"avatars/user_{current_user.id}.png"
    policy = s3.generate_presigned_post(
        Bucket=settings.S3_AVATARS_BUCKET,
        Key=s3_key,
        Fields={"acl": "public-read", "Content-Type": "image/png"},
        Conditions=[["content-length-range", 100, 5242880]],
        ExpiresIn=600
    )
    return {"upload_policy": policy, "target_key": s3_key}
